const mem = std.mem;

pub fn translate(allocator: mem.Allocator, phrase: []const u8) mem.Allocator.Error![]u8 {
    var words = std.ArrayList([]const u8).init(allocator);
    defer words.deinit();

    var start: usize = 0;
    var i: usize = 0;
    while (i < phrase.len) : (i += 1) {
        if (phrase[i] == ' ') {
            if (i > start) {
                try words.append(phrase[start..i]);
            }
            start = i + 1;
        }
    }
