        try words.append(phrase[start..]);
    }

    var result = std.ArrayList(u8).init(allocator);
    defer result.deinit();

    for (words.items, 0..) |word, idx| {
        if (idx > 0) {
            try result.append(' ');
        }
        const split = findSplitIndex(word);
        try result.appendSlice(word[split..]);
        try result.appendSlice(word[0..split]);
        try result.appendSlice("ay");
    }

    return result.toOwnedSlice();
}

